local rows = text.values
rows["25:937124436"]="리치 왕 당신을 기다리고 있습니다!"
rows["25:941282735"]="@미티크 34@하이 블레이드"
rows["25:95281191"]="이 물건은 심각해 보이네"
rows["25:95331289"]="전력 관통"
rows["25:956948541"]="에스도라를 요구합니다."
rows["25:962037175"]="\"그건 우는 폭풍\"이라고"
rows["25:982424097"]="@미티크 28@하이 블레이드"
rows["25:985699197"]="이거로 이동해"
rows["25:986897626"]="\"성욕을 인정하겠다\""
rows["25:989963548"]="자브 크로스"
rows["25:991305332"]="잠깐, 코도스는 알을 낳을 수 있어?"
rows["25:999625104"]="세련된 분위기"
rows["260:1708165225"]="당신 의  ⁇  깃 스카버 를 불러 주십시오. 그 눈 이 당신의 여행 의 그림자를 드러내도록 하십시오. 밤 을 울리는 찢어진 깃털 으로 덮여 있는 이 항상 존재 하는 동반자 는 당신 의 어깨 에서 감시 하고 있으며, 생명 과 죽음 사이의 균형 에 대한 추울 한 상기제 입니다."
rows["260:337712743"]="화살표와 화살표 인스카네이션을 포함하고 있는 화장품 무기 세트 \010\010이 제품은 Transmogrification와 함께 사용되도록 되어 있습니다. 당신은 Vanity 컬렉션에서 화장품 세트가 어떻게 보이는지 볼 수 있습니다. 다른 플레이어, 경매소 또는 잃어버린 가게에서 얻을 수 있습니다."
rows["260:473562951"]="마법으로 당신의 극대화 기회를 추가로 증가시키고 물리적인 공격에 의해 타격을 당할 때 다음 그림자 발트 또는 불타는 주문의 cast 시간을 줄일 수있는 기회를 제공합니다 이 효과는 지속되며 매 8 초마다 한 번 이상 발생하지 않습니다."
rows["260:480572103"]="2 활과 1 화살 인자네이션을 포함하는 화장품 무기 세트. \010\010이 제품은 Transmogrification와 함께 사용되도록 되어 있습니다. 당신은 Vanity 컬렉션에서 화장품 세트가 어떻게 보이는지 볼 수 있습니다. 다른 플레이어, 경매소 또는 잃어버린 가게에서 얻을 수 있습니다."
rows["261:1050168670"]="적 목표물에 악마의 씨앗을 심어 넣고, 암흑 피해 를 일으킨다 목표가 전체적인 피해를 입거나 죽으면, 씨앗은 목표로부터 암흑 피해를 미터 내에 있는 모든 적에게 부과합니다. 매치마다 하나의 부패 주문만 하나의 목표에 활동할 수 있습니다."
rows["261:1881093105"]="- 명성 또는 새로운 캐릭터 중 레벨 1에서 활성화 될 수있는 무작위 Lucky Skill 카드입니다.\010골든스킬 카드는 레벨링 중 특정 주문을 작성할 수 있다고 보장합니다\010- 골든 스킬 카드는 당신의 수도 시티의 실라스에서 금으로 얻을 수 있습니다."
rows["261:406964511"]="이 물 원자 는 광명 도시 의 열호가 숭배 하는 빛 으로 감동 받은 많은 생물 들 가운데 하나 만다. 병등 어린이 들 은 경호적 인 보호자 로 설정 된 그들의 땅 에서 그 와 같은 수많은 다른 것들을 풀어 준다."
rows["262:492190137"]="승천에 부합할 자격이 없다고 판단된 이 동반자를 불러오도록 가르치고 있는 발키르는 용의의 방에서 추방 당했으나, 이제 그녀는 당신을 보호하고 보호하겠다고 약속합니다.\010\010이건 전투가 아닌 동반자입니다."
rows["262:952190883"]="모든 미사 공격은 추가로 신성 피해. 단일 목표물을 공격하거나 공격하는 능력과 함께 사용되면, 이 추가 신성 피해 이 모든 2 이 봉사의 에너지는 적을 판단하여 즉시  신성 피해."
rows["263:1853812669"]="이 친구를 불러내는 법을 가르쳐줍니다.\010\010|cFFFFD100비프 부프. 나는 당신의 코글리 장치입니다. 당신은 마나폭풍에 도움을 찾고 있습니까? 나는 당신의 물건을 수리하고 당신의 재화를 판매 할 수 있습니다.|r\010\010|cFFFFD100코글리는 마나폭풍.|r\010\010이건 전투가 아닌 동반자입니다."
rows["264:1328367051"]="이 해는 지구를 모든 열로부터 깨끗하게 합니다. 야드 안에 있는 적들은 얼음 속에 갇혀 있어, 그들을 추운열에 감염시키고 어떤 행동을 하지 못하게 합니다. 적들은 추운다고 간주되지만 질병 이외의 다른 손상은 얼음을 깨게 됩니다."
rows["264:2027940437"]="병이 적을 해치면, 당신의 승부차기와 동등한 기회가 있습니다. 극대화 그 공격은 목표물과 내부의 모든 적에 추가적인 피해를 줄 가능성이 있습니다. 8 해상을 받으며 취소되는 주문의 영향으로 어떤 목표물을 무시합니다."
rows["264:238385216"]="돌고래 토템을 공격하는 적들은 스톤클라브 토템이 당신의 모든 토템을 보호하고 피해를 흡수하도록 해줍니다."
rows["265:277349982"]="명성 또는 새로운 캐릭터에서 레벨 1에서 사용할 수있는 무작위 인재 기술 카드 5을 포함합니다.\010\010재능기부 자격증은 다양한 품질의 특정 인재를 작성할 수 있는 보장입니다.\010\010재능 기술 카드 패키지는 주로 수도 시라스 다크문에서 얻습니다."
rows["265:74947164"]="모든 마법에 대한 저항을 증가시키고 당신의 마나 또한, 당신에게 대항하는 모든 악용 마법 효과의 기간은 단 1 종류의 갑옷 마법을 만 매기에 언제든지 활동할 수 있습니다."
rows["266:1620347331"]="다음 번에 피해를 입으면 치료할 수 있는 주문을 씌운다. 치유가 발생하면, 마운드 안에 있는 파티 또는 공격 멤버에게 Mending의 기도가 뛰어납니다. 시간까지 뛰어내리며 모든 도약을 한 번에 한 목표에만 붙일 수 있습니다."
rows["267:313162202"]="무사히 참가자의 건강을 희생하여 유죄보호자를 소환하는 의식이 시작됩니다. 성행과 완료하려면 캐스터와 4 추가 파티 구성원이 필요합니다. 참여하기 위해 모든 플레이어는 포털을 오른쪽 클릭하고 의식이 완료 될 때까지 움직이지 않으면 안 됩니다."
rows["267:65560565"]="네파리안의 사망을 증명하는 공식 문서\010\010이 문서를 다음 문서 중 하나에 가져와 보상을 받으세요.\010 - 크로마시 홀드 (오그리마) 에서 트롤\010 - 고왕 볼바르 포드라곤 스톰윈드  ⁇  (스톰윈드).\010 - 바론 레빌가즈, 부티 베이 호네의 상위 배에"
rows["269:1243889405"]="보호적 인 시선을 집단 또는 공격 목표물에 집중하여, 그 피해를 줄이고, 그 위협을 당신에게 전달합니다. 또한, 공격에 의해 공격당할 때마다 당신의 Taunt 냉각은 신선됩니다. 이 효과는 한 번에 하나의 목표에만있을 수 있습니다."
rows["269:1309058110"]="칼레고스는 그의 말에 충실하여 안비나의 보호자가 되었으며, 그녀는 그들의 고향을 재건하는 데 혈액 엘프들에게 도움을 주었다. 그러나 불타는 군단은 그녀의 주인인 악마의 주왕 킬제덴을 아제로스로 데려오기 위해 그녀를 사용할 것으로 기대했다."
