rows["271:1305180515"]="사용에 대해 Relentless (랭크 1) 를 가르쳐줍니다.\010\010|cFFFFCC00Fel 민첩성:|r\010|cFFFFFFFF급 1|r\010모든 냉각은 |cffFF99002%|r로 감소합니다. 명예나 경험을 제공하는 모든 살인 후에.\010\010이 아이템은 당신의 허무함 컬렉션에 추가되어 모든 Felforged 캐릭터에 사용할 수 있습니다."
