rows["271:1662303369"]="디스펜서는 다음과 같이 작용한다.\010기로마틱 마이크로 조절기\010아크라이트 스펜어\010금속 해머,\010광산 픽\010스킨닝 칼\010목재축\010가상 잉크 세트\010철학자 돌\010|cff00ff00개선:\010론드 아르카나이트 로드|r\010\010|cffFF0000이 항목이 파괴되면 모든 업그레이드가 손실됩니다!|r"
rows["271:277744860"]="디스펜서는 다음과 같이 작용한다.\010기로마틱 마이크로 조절기\010아크라이트 스펜어\010금속 해머,\010광산 픽\010스킨닝 칼\010목재축\010가상 잉크 세트\010철학자 돌\010|cff00ff00개선:\010 ⁇  에테르니움 로드|r\010\010|cffFF0000이 항목이 파괴되면 모든 업그레이드가 손실됩니다!|r"
rows["271:462968176"]="오닉시아의 사망을 증명하는 공식 문서\010\010이 문서를 다음 문서 중 하나에 가져와 보상을 받으세요.\010  - 룬타크 경주, 오그리마 은행 밖에서\010  - 메이저 매팅리, 스톰윈드 무역 구역 밖에서\010  - 바론 레빌가즈, 부티 베이 호네의 상위 배에"
rows["271:510906604"]="당신의 라이트닝 볼트, 체인 라이트닝, 라바 래쉬 및 쇼크 주문이 해치는 피해를 증가시켜서 당신의 프로스트브랜드 공격 효과에 의해 영향을 받는 목표물에 영향을 미칩니다. 그리고 당신의 프로스트 쇼크는 당신이 나보다 거리에 있는 목표물에 사용될 때 얼음으로 목표물을 뿌리 내리는 기회를 가지고 있습니다."
