rows["273:177009137"]="사용에 대해 Relentless (랭크 2) 를 가르쳐줍니다.\010\010|cFFFFCC00불후의:|r\010|cFFFFFFFF급 2|r\010재생 |cffFF99004%|r 최대 마나 명예나 경험을 주는 모든 살인 후\010\010이 아이템은 당신의 허무함 컬렉션에 추가되어 모든 Felforged 캐릭터에 사용할 수 있습니다."
rows["273:797356284"]="사용에 대해 Relentless (랭크 3) 를 가르쳐줍니다.\010\010|cFFFFCC00불후의:|r\010|cFFFFFFFF급 3|r\010재생 |cffFF99006%|r 최대 마나 명예나 경험을 주는 모든 살인 후\010\010이 아이템은 당신의 허무함 컬렉션에 추가되어 모든 Felforged 캐릭터에 사용할 수 있습니다."
rows["274:1206784123"]="어둠을 넘어서서 적에서 적으로 10 매번 적을 공격하는5 두 무기를 모두 사용해서 5 공격이 이루어지고, 그 기간 동안 피해를 더해지게 됩니다. 같은 목표를 여러 번 타격할 수 있습니다. 보이지 않는 또는 숨겨진 목표물을 타격 할 수 없습니다."
rows["274:1230259987"]="콤보 포인트에 대한 손상을 일으키는 완료 동작과 각 추가 에너지 포인트를 (최고의 추가 에너지) 추가 손상으로 변환합니다. 손상은 전투력로 증가합니다.\010   1 점: 손해\010   2 점: 손해\010   3 점: 손해\010   4 점: 손해\010   5 점: 손해"
rows["274:1974251317"]="당신은 유령 영혼을 목표물에 보내며, 암흑 피해를 처리하고, 당신의 암흑 피해-오프 타임 효과로 목표에 의한 모든 피해를 증가시킵니다."
rows["274:753656392"]="건강 상태가 35% 이하에 있으면 모든 피해가 줄어들고 피로블라스트 매기의 투기 시간은 초으로 줄이고 냉각은 초로 증가합니다. 또한, 당신에게 대한 연동 및 원격 공격은 공격자의 주요 손과 원격 무기를 무력화 할 수있는 기회를 가지고 있습니다."
rows["274:761139222"]="[D에 대한 보이지 않는 투하를 미화, 위협을 초.] 어떤 행동을 수행하면 효과가 취소됩니다. 보이지 않지만 다른 보이지 않는 목표물을 볼 수 있습니다. 그리고 보이지 않는 것을 볼 수 있는 사람들 만. 12d."
rows["274:971811229"]="사용에 대해 Relentless (랭크 5) 를 가르쳐줍니다.\010\010|cFFFFCC00불후의:|r\010|cFFFFFFFF급 5|r\010재생 |cffFF990010%|r 최대 마나 명예나 경험을 주는 모든 살인 후\010\010이 아이템은 당신의 허무함 컬렉션에 추가되어 모든 Felforged 캐릭터에 사용할 수 있습니다."
rows["275:1276758377"]="@미티크@네파리안의 죽음을 증명하는 공식 문서\010\010이 문서를 다음 문서 중 하나에 가져와 보상을 받으세요.\010 - 크로마시 홀드 (오그리마) 에서 트롤\010 - 고왕 볼바르 포드라곤 스톰윈드  ⁇  (스톰윈드).\010 - 바론 레빌가즈, 부티 베이 호네의 상위 배에"
rows["276:221596688"]="스코르치, 파이어볼 및 프로스트파이어 볼트와 함께 추가적으로 공격할 확률을 높이고 당신의 손상된 스코르치 주문은 극대화 그 목표에 대한 기회는 59d."
rows["277:988636259"]="@Ascended@네파리안의 죽음을 증명하는 공식 문서\010\010이 문서를 다음 문서 중 하나에 가져와 보상을 받으세요.\010 - 크로마시 홀드 (오그리마) 에서 트롤\010 - 고왕 볼바르 포드라곤 스톰윈드  ⁇  (스톰윈드).\010 - 바론 레빌가즈, 부티 베이 호네의 상위 배에"
rows["278:1345854588"]="현재 당원 또는 침략 멤버가 당신의 트릭 오브 트레이드의 목표물이 됩니다. 다음 해로운 공격으로 인한 위협과 그 이후에 대한 모든 행동이 목표물에 전달됩니다. 또한, 이 기간 동안 목표에 의한 모든 피해는 증가합니다."
rows["278:1791456338"]=" ⁇ 은 에너지로 목표를 폭발시키고, 비전 피해을 처리한다. 아카네 블라스트를 던질 때마다 모든 아카네 주문의 손상은 증가하고 마나의 비용이 아카네 폭발이 시간까지 퍼져나가는 효과 스택으로 증가합니다. 그리고 그 동안 또는 아카네 블래스트를 제외한 어떤 비전 피해 마법을 던지는 때까지 지속됩니다."
rows["278:935000745"]="사냥꾼의 표적을 목표에 올려다보며, 전투력 이 능력의 목표물도 사냥꾼에게 항상 볼 수 있습니다."
