rows["280:1341493289"]="수호자의 영을 우호적 목표물을 감시하도록 촉구합니다. 영은 목표물이 받는 치유를 %로 증가시키고 또한 자신을 희생함으로써 목표가 죽는 것을 방지합니다. 이 희생은 효과를 끝내고 목표물을 최대의 건강으로 치료합니다."
rows["280:165165818"]="오른쪽 클릭!  \010\010클래스를 선택하고 수신: \010-  ⁇ 어있는 스카이드레의 신비로운 레갈리아 \010-  ⁇ 어있는 스카이드레의 거칠고 있는 레갈리아 \010- 마녀사살자 대검 \010- 마녀살인자 블래스터 \010- 마녀살인자 횡포 \010- 오브시디언 불멸의 다크하우드의 리인\010-  ⁇ 어있는 스카이드레의 신비한 위장"
rows["280:210898859"]="즉시  ⁇ 돌이 근처의 목표에 도달하고 다음에는 매초마다  ⁇ 돌 공격을 수행 할 것입니다. Bladestorm 의 영향 아래 있으면 움직일 수 있지만 다른 능력을 수행 할 수는 없지만 자비를 느끼거나 후회하거나 두려움이 없으며 죽기 전까지는 막을 수 없습니다."
rows["280:226186371"]="@미티크 레이드@네파리안의 죽음을 증명하는 공식 문서\010\010이 문서를 다음 문서 중 하나에 가져와 보상을 받으세요.\010 - 크로마시 홀드 (오그리마) 에서 트롤\010 - 고왕 볼바르 포드라곤 스톰윈드  ⁇  (스톰윈드).\010 - 바론 레빌가즈, 부티 베이 호네의 상위 배에"
rows["281:1343106774"]="당신이 겪는 모든 피해를 증가시키고 당신의 애완 동물이 야생 분노의 영향에 처해있는 동안 당신은 또한 더 많은 피해를 초래하고 마나 화를 내면서도 자비를 느끼거나 후회하거나 두려워하지 않으며 죽기 전까지는 막을 수 없습니다."
rows["281:1882399330"]="팔라딘의 최대 건강에 해당하는 금액으로 친근한 표적을 치료합니다. 스스로 사용되면 팔라딘은 신성 방패, 신성 보호, 보호 손 또는 자기 목표치인 손 위에 다시 공격할 수 없습니다. 또한 복수 분노를 사용하는 동안 자신을 사용할 수 없습니다."
rows["283:1195757151"]="손상을 일으키는 마지막 동작과 목표물을 놀라게 한다.\010   1 점: 손해, 1 세\010   2 점: 손해, 2 세\010   3 점: 손해, 3 세\010   4 점: 손해, 4 세\010   5 점: 손해, 5 세"
rows["283:247843828"]="오른쪽 클릭으로 빌드 드래프트를 시작할 때 선택해야 할 추가 빌드 카드를 영구적으로 잠금 해제합니다. \010\010빌드 드래프트에서 최대 16 카드 슬롯을 열 수 있습니다.\010\010이 영역의 모든 캐릭터들을 위한 잠금 잠금을 해제합니다.\010\010중요한 점: 최상의 결과를 얻기 위해 빌드 드래프트에서 역할 선택 전에 이것을 사용하십시오."
rows["284:532834576"]="고대 마법 의 유물 을 아직도 보관 하는 트롤 유적. 사랑과 후회 는 서로 얽혀 있을 때 별 들 을 움직일 수 있는 매력을 엮는다. 고대 아즈달라르 시 의 폐허 가 올라가는 다운라이스 섬 의 높은 산 정상 에, 그 목적 은 아직 발견 될 수 있다."
rows["285:1111281176"]="@미티크 레이드@ 오닉시아의 사망을 증명하는 공식 문서.\010\010이 문서를 다음 문서 중 하나에 가져와 보상을 받으세요.\010  - 룬타크 경주, 오그리마 은행 밖에서\010  - 메이저 매팅리, 스톰윈드 무역 구역 밖에서\010  - 바론 레빌가즈, 부티 베이 호네의 상위 배에"
rows["285:1667504720"]="오닉시아의 사망을 증명하는 공식 문서.\010\010이 문서를 다음 문서 중 하나에 가져와 보상을 받으세요.\010  - 룬타크 경주, 오그리마 은행 밖에서\010  - 메이저 매팅리, 스톰윈드 무역 구역 밖에서\010  - 바론 레빌가즈, 부티 베이 호네의 상위 배에"
rows["286:713073202"]="@Ascended Raid@ 공식 문서, 오닉시아의 사망을 증명하는 문서.\010\010이 문서를 다음 문서 중 하나에 가져와 보상을 받으세요.\010  - 룬타크 경주, 오그리마 은행 밖에서\010  - 메이저 매팅리, 스톰윈드 무역 구역 밖에서\010  - 바론 레빌가즈, 부티 베이 호네의 상위 배에"
rows["287:1528237879"]="목표물이 손상될 때마다 그들은 성적인 방패를 얻으며, 피해를 흡수하고 빛의 번개로 비평적으로 타격을 받을 확률을 높이는 것입니다."
rows["287:1554507121"]="아나스트리아의 선스트라이더는 켈라스 왕자 중 마지막 고령왕이다. 그의 통치 기간은 최소 3천 년 동안 지속되었으며, 켈라스의 계속된 존재를 위협하는 여러 분쟁으로 꼽혔으며 악의 공작 아르타스 메네틸의 손에 의해 파괴되었습니다."
