rows["28:993477003"]="아카인 모테스"
rows["28:994193012"]="\"빙상 마법사\""
rows["291:1856383656"]="d에 대해 적을 판단하는 봉사의 힘을 풀어주고, 심판된 적에 대한 공격을 통해 공격자가 최대의 건강을 위해 치유 할 기회를 제공합니다. 추가적인 판단 효과를 위해 개별 봉사를 참조하십시오."
rows["294:1071502668"]="고대 트롤 동전, 앞면 에는 원시 짐승 의 형상 이 새겨져 있으며, 뒤쪽 은 깨어난 경호자 들 의 표적을 지니고 있다."
rows["294:2043345914"]="포커스 캐스팅 효과는 미레 또는 랜딩의 희생자 된 후 지속되는 포커스 캐싱 효과를 얻을 수있는 기회를 제공합니다 극대화. 포커스 캐팅 효과는 프레스 마법을 던지는 동안 손상적인 공격으로 인한 역전력을 감소시키고 인터럽트 효과의 기간을 28s2%로 줄입니다."
rows["295:1364676146"]="사제 는 죽음 을 거쳐 전체 정신을 증가 시키며, 구원 의 영이 된다. 그 후 에 구원 의 영 은 어떤 마법을 하거나 효과 를 통해 움직이지 못 하며 공격 할 수 없고 공격 받을 수도 없읍니다. 이 형태 에서 사제 는 아무 치유 마법을도 무료로 던질 수 있습니다. 그 효과 가 끝나면 사제 는 죽습니다."
rows["295:775543682"]="이 형태는 당신의 장갑을 % 증가시키고, 손상을 % 증가시키며, 당신이 미사 공격에 의해 심각하게 타격을 받을 확률을 6% 감소시키고, 스턴 및 함정 효과의 기간을 줄여줍니다. 당신은 당신의 정상적인 능력 외에도 몇 가지 독특한 악마 능력을 얻을 수 있습니다. 3 분 냉각."
rows["297:1703646441"]="또한, 당신의 패크 리더 능력은 영향을 받은 대상들이 메리 또는 랜테인지 공격으로 심각한 타격을 당할 때 전체 건강의 이익을 위해 스스로를 치유하도록 한다. 치료 효과는 6 초마다 한 번 이상 발생 할 수 없다. 이 외에도, 당신이 이 치유로부터 혜택을 받을 때 최대 마나을 얻을 수 있다."
rows["297:1929762677"]="이 그림 은 더 나은 날 을 보였습니다. 그 그림 은 베개 의 침대에 누워 있는 여자 를 묘사 하고 있습니다. 이 는 이상한  ⁇ 증 으로 고통 받고 있는 것 같습니다. 사실, 그것은 나이 에 따라 갈라진 화면 만입니다. 하지만 그 그림 에 관한 어떤 것 은 당신을 불안 하게 합니다. 그녀의 눈 들 이 당신 의 모든 움직임을 추적 하는 느낌 을 떨칠 수 없습니다."
rows["297:763274216"]="맑은 빛 은 그 들 의 눈 에  ⁇ 어 있는 것 이 아니라, 그 들 의 눈 에는 웅장 한 빛 은 그 들 에게 나타났으며, 그 들 은 그 들 의 마음 을 굽히지 않고, 그 들 의 생각 을 굽히기 까지는 계속 해왔을 것 이다."
rows["299:619468045"]="이 능력은 활성화되면 마글 (곰) 의 목표에 도달할 수 있는 능력을 유발하고 냉각을 하지 않으며, \010\010공포의 영향을 없애고, 두려움에 대한 면역력을 유지합니다."
