rows["29:998728111"]="@미티크 39@사령관의 눈"
rows["300:1186558281"]="그들은 오고 있습니다. 또 다른 파도가 언덕을 오르고 있습니다. 마지막과 마찬가지로. 모든 사람들이 사라졌습니다. 나는 마지막입니다. 거의 서있다. 내 칼은 아무것도 찢어졌다. 내 팔은 그것을 들어올리지 않습니다. 이 그들의 것보다 내 손으로 끝나는 것이 좋습니다. 그들이 살아있는 사람들에게 무엇을 하는 것... 나는 더 나은 것을 발견하지 않을 것입니다.\010\010 - 발타이르"
rows["300:1570820684"]="이 돌 안에 암흑의 지능이 뿌리를 내리고 바다 반대편에서 왔고 암흑 숲의 검은 염소 자녀들은 수천 명에 달한다. 그들의 어머니의 비참한 굶주림에서 탈출한 사람들은 결국 가장 깊은 곳에 봉착되었다."
rows["300:929569517"]="내 몸의  ⁇ 을 더 많이 전투력 고양이, 곰, 류곰의 형태에 따라 전투력 또한, 당신의 마지막 움직임은 코보 포인트에 따라 다음 자연 주문을 만들 수있는 기회가 있습니다 10 초. 즉흥적인 캐스트 매력을 갖게 됩니다."
rows["301:138179163"]="발자기는 번개 공으로 둘러싸여 있다. 마법, 미레 또는 멀리 떨어진 공격이 발자기를 때면 공격자는 자연 피해에 의해 타격을 받게 된다. 이것은 번개 공을 사용한다. 몇 초마다 한 공만 발사된다."
rows["302:1576735409"]="이 마법을 활성화하면 극대화 손해 보너스 화염 피해 %로 주문을 합니다. 화염 피해 주문을 눌러서 극대화 기회 화염 피해 이 효과는 불타기 주문으로 비 주기적인 비판적 공격을 일으키는 동안 지속됩니다."
rows["303:532169343"]="당신의 무기가 줄어들면서 당신은 짐승을 숙제하는 데 집중합니다 20 만약 어떤 이유로든 짐승의 관심을 잃으면, 숙달 과정이 실패할 것입니다. 일단 숙달되면, 짐승은 매우 불행하고 불충분해질 것입니다. 애완 동물을 행복하게 만들기 위해 즉시 먹이를 먹으려 합니다."
rows["303:773166586"]="당신은 즉시 얻을 수있는 기회가 있습니다 마나 마치 물 방패 궤도를 사용했을 때 치유파나 삐걱거리는 마법을 통해 중요한 효과를 얻을 수 있고, 작은 치유파 마법을 통해 중요한 영향을 받을 수 있는 기회와"
rows["305:730814981"]="만약 당신이 스타파이어로 비평적으로 타격하면 화이트가 해친 피해를 증가시킬 가능성이 있습니다. 극대화 별불에 의해 모든 효과는 지속되고 각각의 다른 초 냉각을 가지고 있습니다. 두 효과도 동시에 발생할 수 없습니다."
rows["306:2115398366"]="반마법 껍데기로 죽음의 기사에게 둘러싸고, 해로운 주문으로 인한 피해를 흡수하고 (사격자의 건강의 최대) 해로운 마법 효과를 방지합니다. 룬 마력- 마지막 07d."
rows["308:120530034"]="팔라딘의 최대 건강과 동등한 금액에 친절한 목표를 치료하고 그들의 마나를 회복합니다. 스스로 사용되면 팔라딘은 신성한 방패, 신성한 보호, 보호 손 또는 자기 목표치인 손에 다시 타겟을 할 수 없습니다. 또한 복수 분노를 사용하는 동안 자신을 사용할 수 없습니다."
rows["308:460020858"]="사냥꾼은 뱀의 측면을 차지하고, 거리를 두고 전투를 일으켜 재생한다 마나 그러나 전체 피해를 줄이는 것 또한, 당신은 최대 마나 각 초에 얻을 수 있습니다. 마나 획득한 것은 당신의 거리를 가진 무기 속도에 기초합니다. 거리를 가진 무기 필요합니다. 한 번에 하나의 측면이 활성화 될 수 있습니다."
rows["309:1473417049"]="플래시 치유, 더 큰 치유 및 회개 (치료) 주문의 중요한 효과를 증가시키는 약화된 영혼 효과에 의해 영향을 받는 목표물에, 그리고 당신은 모든 친근한 파티에 대한 피해를 줄일 수있는 기회를 가지고 있습니다"
