rows["310:1894913427"]="캐스터는 물의 지구로 둘러싸여 있으며, 마나초당 5을 부여한다. 마법이나 미러 또는 멀리 떨어진 공격이 캐스터를 때, 마나은 캐스터에 복원된다. 이것은 하나의 물 구름을 소비합니다. 몇 초마다 오직 한 개의 지구만 활성화됩니다. Lasts 한 번 동안 샤맨에서 활동할 수 있는 유일한 원자 방패입니다."
rows["311:23187676"]="순수한 그림자 에너지로 분산하여 피해를 줄이고 공격하거나 주문을 할 수 없지만 재생됩니다  마나 분산의 모든 초점은 놀라거나 두려워하거나 침묵을 유지하면서 투입될 수 있습니다. 그리고 모든 함정과 움직임을 방해하는 효과를 제거합니다."
rows["312:1018047476"]="거짓된 서류를 작성하여 얼라이언스 최근 화재와 파괴에 썬더 블러프5개 문서에 언급되어 있습니다 얼라이언스 당신이 카이타에게 넘겨준 5명의 평화로운 사람들이 그 숫자와 일치하는 것은 우연인가?"
rows["312:1543756047"]="곰 모양으로 형태를 변경하여, 매매 전투력을 3로 증가시키고, 천과 가죽의 장갑 공헌을 %로 증가시키고, 체력에 의해 또한 포스터를 폴리모프 효과로부터 보호하고 다양한 곰 능력을 사용할 수 있습니다.\010\010형태를 바꾸는 행위는 폴리모프와 운동에 영향을 미치는 효과를 방출합니다."
rows["313:1149968516"]="이 표지판 에는 작은 글자 로 된 문장이 눈 을 사로잡는다. '작업 짐승 은 죽은 자 들, 부활 한 사람, 좀비 들 또는 죽음 가까이 에 있는 어떤 존재 가 경험 한 경우 에도 발생할 수 있는 부작용 에 대해 아무런 책임도 지지 않는다.'"
rows["313:1255145856"]="이 산이 날 수 있는 방법을 가르쳐줍니다\010\010이 산은 미친 도금사에서 지옥불 성곽 안에 깊이 만들어졌습니다. D defiled annihilator는 철의 금속 작업 지식을 호드와 불타는 군단 의 혼란스러운 fel 에너지로 결합하여 강철과 불의 불성스러운 연합으로 만들었습니다."
rows["313:378106417"]="당신은 더 이상 새로운 능력을 레벨까지 롤 할 수 없습니다 62당신은 당신의 능력의 본질을 얻을 수 있는 수준에 저장할 것입니다 53 이 60그리고 당신은 당신의 저축을 쓸 수 있습니다 8 두 단계의 능력 본질 50 그리고 60 재능은 레벨에 도달하면 60이 아이템은 또한 당신이 더 이상 능력을 발휘하지 못하는 수준에서 운의 스크롤을 부여합니다!"
rows["314:1044885954"]="이 산이 날 수 있는 방법을 가르쳐줍니다\010\010이 산은 미친 도금사에서 지옥불 성곽 안에 깊이 만들어졌습니다. Felsteel Annihilator는 철의 금속 작업 지식을 호드와 불타는 군단 의 혼란스러운 fel 에너지로 결합하여 강철과 불의 불결한 연합으로 만들었습니다."
rows["314:1951034501"]="반려견은 반려견으로 변신하여 반려견을 떠돌아다니게 합니다. 반려견은 공격하거나 주문을 던질 수 없지만 매우 빠르게 재생됩니다. 어떠한 손해도 목표물을 정상 형태로 되돌릴 것입니다. 한 번에 하나의 목표물이 다형화 될 수 있습니다. 동물, 인간과 크리터에서만 작동합니다."
rows["314:959652124"]="바다가 이 지역을 군도로 바꾸기 전에 먼 곳에서 여행한 비루클 순례자의 뼈. 수백 년 동안, 비루클은 짐승을 물리치고 그 유해들을 산으로 새겨낸 영웅들을 기리기 위해 모였습니다. 그들은 그들의 승리가 피라스적 승리로 불과하다는 것을 결코 이해하지 못했습니다."
rows["315:869134291"]="이 산이 날 수 있는 방법을 가르쳐줍니다\010\010이 산은 미친 도금사에서 지옥불 성곽 안에 심히 만들어졌습니다. 부패한 해살기는 철의 금속 작업 지식을 호드와 불타는 군단 의 혼란스러운 fel 에너지로 결합하여 강철과 불의 불성스러운 연합으로 만들었습니다."
rows["316:291912874"]="챔피언 쿠르건의 지휘 문서, 실제로는 스크립트의 수집입니다. 하지만 모든 선과 스펙 (인크, 피, 그리고 더 나쁜 것) 은 지역의 지도와 비슷한 것을 보여줍니다."
rows["317:1393324550"]="외형이 급격한 곰 모양으로 변화하여, 매매 전투력를 증가시켜 3, 천과 가죽의 유물에서 갑옷의 기여를 %로 증가시키고 체력 또한 포스터를 폴리모프 효과로부터 보호하고 다양한 곰 능력을 사용할 수 있습니다.\010\010형태를 바꾸는 행위는 폴리모프와 운동에 영향을 미치는 효과를 방출합니다."
rows["317:7676407"]="친선적 목표물에 축복을 배치하여 모든 원천에서 얻은 피해를 줄이고 힘을 증가시키고 체력 또한, 목표가 블록, 파리 또는 동참 공격을 피하면 목표물이 최대 표시되는 이익을 얻을 수 있습니다 마나. 플레이어는 한 번 팔라딘당 한 번만 사용할 수 있습니다."
rows["318:1734165431"]="명성 또는 새로운 캐릭터 중 레벨 1에서 활성화 될 수있는 무작위 Lucky Skill 카드입니다.\010럭키 스킬 카드는 특정 주문을 작성할 확률을 크게 증가시킵니다.\010\010이 사진은 시ilas darkmoon의 승천표로 얻었습니다.\010골든 스킬 카드는 당신의 수도 시티의 실라스에서 금으로 얻을 수 있습니다."
