rows["323:1814354872"]="이 상자는 장갑 세트를 포함하고 있습니다. 헤크스플라임 코벤 매술 시각의 혈통 포옹은 별도의 아이템으로 판매됩니다. \010\010이 제품들은 Transmogrification와 함께 사용될 예정입니다. 이 제품들은 다른 플레이어, 경매소 또는 잃어버린 가게에서 구입할 수 있습니다."
rows["324:667047907"]="이 산이 날 수 있는 방법을 가르쳐줍니다\010\010이 산은 미친 도금사에서 지옥불 성곽 안에 심히 만들어졌습니다. 얼음  ⁇  해살기는 철의 금속 작업 지식을 호드와 불타는 군단 의 혼란스러운 fel 에너지로 결합하여 강철, 얼음 및 불의 불성스러운 연합으로 만들었습니다."
rows["328:922177846"]=" ⁇ 은 무해한 터키로 변신하여,  ⁇ 을 따라다니도록 강요합니다.  ⁇ 은 공격하거나 주문을 던질 수 없지만 매우 빠르게 재생됩니다. 어떠한 손해도 목표물을 정상 형태로 되돌릴 것입니다. 한 번에 하나의 목표물이 다형화 될 수 있습니다. 짐승, 인간과 크리터에서만 작동합니다."
