rows["330:1069514762"]="야생충 (곰) 과 야생충 ( 고양이) 를 가르칩니다.\010\010야생 충전 (곰) - 적을 충전하도록 유도하여, 투입되는 매력을 무동화시키고 중단시키는 이 능력은 곰 형태와 디렉터 곰 형태로 사용될 수 있습니다. 15 두 번째 냉각.\010\010야생 무력 (Cat) - 적 뒤에 뛰어들어, 그들을 놀라게 합니다  30 두 번째 냉각."
rows["330:1173709701"]="원수에게 무해한 토끼로 변신시켜서, 그 토끼는 도랑할 때 공격하거나 주문을 던질 수 없지만 매우 빠르게 재생됩니다. 어떠한 손해도 목표물을 정상 형태로 되돌릴 것입니다. 한 번에 하나의 목표물이 다형화 될 수 있습니다. 짐승, 인간과 크리터에서만 작동합니다."
rows["330:1240159364"]="죽음의 포옹 속에서 혼자 서있어요\010더 이상 내 집을 찾지 않겠어\010더 이상 슬픔, 더 이상 눈물\010더 이상 오래된 두려움의 반향이 없을 겁니다.\010\010육체는 추워지고 심장이 느려지고\010삶이 사라지면서 내 힘이 커집니다.\010마지막 눈물이 남아있지 않아\010내가 고통 없는 길을 택하거든\010\010내 마지막 조각...\010나머지는 침묵이야"
rows["332:1035605286"]="원수에게 무해한 뱀으로 변신시켜서, 1시간 동안 횡단하는 것을 강요합니다. 도랑을 하면서 뱀은 공격하거나 주문을 던질 수 없지만 매우 빠르게 재생됩니다. 어떠한 손해도 목표물을 정상 형태로 되돌릴 것입니다. 한 번에 하나의 목표물이 다형화 될 수 있습니다. 짐승, 인간과 크리터에서만 작동합니다."
rows["332:602412263"]="반려동이 도는 동안 공격하거나 주문을 던질 수 없지만 매우 빠르게 재생됩니다. 어떠한 손해도 목표물을 정상 형태로 변환합니다. 한 번에 하나의 목표물이 다형화 될 수 있습니다. 짐승, 인간과 크리터에서만 작동합니다."
rows["333:1488595451"]="이 문서는 카드거가 쓴 것으로 보이며, 워치프 트랄에게 직접 지시되었다. 이것은 침략 계획과 나루와 빛의 군대에 대한 카드거의 기도의 묘사입니다. 그들은 그 지도를 보내지 않았음에도 불구하고. 당신은 이로부터 기이한 힘을 발산하는 것을 느낄 수 있습니다. 비슷한 약한 서명이 근처에있는 것처럼 보입니다."
rows["334:978509585"]="이 문서는 카드거가 쓴 것으로 보이며 볼바르 포드라곤에게 직접 지시되었다. 이것은 침략 계획과 나루와 빛의 군대에 대한 카드거의 기도의 묘사입니다. 그들은 그 가이드라인을 보내지 않았음에도 불구하고. 당신은 이로부터 기이한 힘을 발산하는 것을 느낄 수 있습니다. 비슷한 약한 서명이 근처에있는 것처럼 보입니다."
rows["335:354519751"]="선발자 (Raid Member) 는 Soulwell을 클릭하여 마스터 헬스톤을 획득할 수 있습니다. Soulwell는 25의 요금 또는 연봉을 지속합니다. 캐스터와 2의 추가 멤버가 의식을 완료하도록 요구됩니다. 참가하기 위해 모든 플레이어는 영혼 포털을 오른쪽 클릭하고 의식이 완료 될 때까지 움직이지 않습니다."
rows["335:618294023"]="세르빈 다레네거의 아들이자 가족의 상속자인 아라톤의 일기\010\010이 문서는 미묘한 내용으로 되어 있으며, 그 문서는 은밀한 내용과 접하고 있다. 일부 페이지들은 개인 일기보다는 사서처럼 보인다. 이 의도적인 모호함은 의심의 여지를 자극하는 데만 작용한다. '엘다르', '잘'', '배송' 및 '굴'이라는 단어들은 반복적으로 등장한다."
rows["339:1586293609"]="이 산을 불러내는 법을 가르쳐줍니다.\010\010속삭이는 봉우리 의 고대 왕 아자르 의 개인적 산. 거짓 로우 의 속임수 가 밝혀졌을 때, 아자르는 충성 스러운 랩터 의 정신 을 일곱 개의 돌판 으로 보호 하였다. 그 다음 에 그는 땅 아래로 들어가서 북쪽 강도 에서 부르짖는 목소리 를 따랐다."
rows["339:364212462"]="레벨 70에 도달하면 4 능력의 본질을 저장한 수준 67에서 70까지 사용할 수 있습니다. 당신이 레벨 50 또는 60에 도달했을 때 추가적인 수준을 선택할 수 있도록 70! 당신은 전체 12 능력의 본질이 3 레벨 50 및 60에 지출 할 것입니다. 당신은 단지 1 레벨 60 인재를 선택할 수 있습니다. 이 항목은 또한 당신에게 운명의 Dice를 부여합니다!"
