rows["341:1753087151"]="미스틱 루너는 미스틱 매혹성 제단에서 새로운 매혹성으로 미스틱 스크롤을 재조성하는 데 사용됩니다. 이것은 미스틱 추출에 대한 경험을 쌓아, 영구적으로 컬렉션에 매혹성을 저장할 수 있습니다.\010\010제단들은 종종 수도 도시들에서 소집되어 있고, 세계 곳곳에서 발견될 수 있습니다. 그들의 위치는 세계 지도에 POI로 표시됩니다."
rows["341:2144578323"]="지뢰 방패로 목표를 보호하여, 손상된 경우 손실되는 캐스팅 또는 채널링 시간을 줄이고 보호 대상 치료에 대한 공격을 유발합니다. 이 효과는 몇 초마다 한 번만 발생할 수 있습니다."
rows["341:946381449"]="이 제품들은 Transmogrification와 함께 사용될 예정입니다. 이 제품들은 다른 플레이어, 경매소 또는 잃어버린 가게에서 구입할 수 있습니다.\010\010이 세트는 몇 가지 추가적인 트랜스모그 옵션을 가지고 있습니다. 다른 조합을 시도하고 멋진 모습을 발견 할 수 있는지 확인하십시오!"
rows["347:255525888"]="Fel Power은 영웅을 강화하는 데 사용됩니다.\010\010레벨을 쌓고 악마 계약과 도전을 완료함으로써 Fel 힘을 얻습니다.\010Fel Power는 자동으로 강력한 퍼커스, 라이딩, 레지온 인그니아를 열고 더 많은 것을 누릴 수 있습니다.\010\010또한 실라스 다크문에서 미스틱 루너, 오브, 스킬카드, 그리고 운명의 손으로도 쓸 수 있습니다."
rows["348:298508305"]="리프레싱 테이블을 만드는 의식이 시작됩니다. 레이드 멤버들은 콘저드 마나 스트루델을 획득하기 위해 테이블을 클릭할 수 있습니다. 테이블은 수수료 또는 50까지 지속됩니다. 캐스터와 2 추가 파티 구성원들이 의식을 완료하도록 요구합니다. 참여하려면 모든 플레이어는 리프레싱 포털사이트를 오른쪽 클릭해야 하며 의식이 완료 될 때까지 움직이지 않습니다."
rows["349:2128444536"]="포함하고 있습니다. \010  \010 - 6x 미스틱 매혹: 전문성 \010 - 전문 분야 II \010 - 전문 분야 III \010 - 전문 분야 IV의 총 \010 - 전문 분야 V \010 - 전문 분야 VI의 총 \010  \010 |cFFFF5500중요해요|r 이 문서를 열고 보상이 받는 캐릭터에 |cFFFF5500그 내용은 전송되거나 복수할 수 없습니다.|r"
