rows["34:974589255"]="미토스 39"
rows["350:1892927098"]=" ⁇  세계벼림@ 조심하세요, 렌즈가 깨졌어요.\010\010고발: 이 아이템은 손상된 렌즈 집합을 갖추고 있습니다. 유리 조각으로 인한 눈 손상을 피하기 위해 극심한 주의를 기울여 처리하십시오. 제조업체는 이 손상 된 장비의 사용으로 인해 발생하는 손해 또는 부작용에 대한 책임을 지지 않습니다. 자신의 위험에 사용하세요."
rows["355:1740101074"]="특화 I의 능력을 배워내기 위해 캐릭터 진전에서 능력 아이콘을 클릭하면 새로운 능력을 선택하여 그 자리를 대신할 수 있습니다.\010\010당신은 마나폭풍, 퀘스트, 던전, 레이드, 콜보드 캐시, 배틀그라운드, 하이 리스크 오픈 월드, 그리고 상승의 마크를 사용하여 캐피탈에서 시ilas 다크문에 대한 퀘스트 체인을 얻을 수 있습니다."
rows["356:955411935"]="이 돌과 그 같은 돌들은 다크스피어 트롤들이 그들의 부족보다 훨씬 오래된 트롤 문명의 거대한 유적들을 발견했을 때 발굴되었습니다. 시험의 계곡 위에 서 있는 두 거대한 석탑은 트롤들이  ⁇ 을 잃었고 얼마나 멀리 떨어진 지 bitterly 상기시켜줍니다."
rows["357:1195181415"]="아타스가 노스렌드로 떠난 후, 리벤다레는 토마스 톰슨이 있었던 로데론 마을에 음식물 배송을 보냈다. 마을 사람들은 무의식적인 좀비로 변했을 때, 토마스는 리벤다레가 반역자라는 것을 이해했습니다."
