rows["370:658060683"]="초청 포털을 만드는 의식이 시작됩니다. 초청 포털은 2 당원 또는 발병 멤버가 대상당원 또는 발병 회원을 초청하는 데 사용할 수 있습니다. 의식 포털은 캐스터와 2 추가 당원 또는 발작 회원이 완료해야합니다. 참가하기 위해 모든 플레이어는 전투에서 벗어나 포털을 오른쪽 클릭하고 의식이 완료 될 때까지 움직이지 않으면 안됩니다."
rows["372:410697561"]="이 문서를 열면 현재 전문 분야에 대한 운명의 스크롤을 얻을 수 있습니다.\010\010당신은 마나폭풍, 퀘스트, 던전, 레이드, 콜보드 캐시, 배틀그라운드, 하이 리스크 오픈 월드, 그리고 상승의 마크를 사용하여 캐피탈에서 시ilas 다크문에 대한 퀘스트 체인을 얻을 수 있습니다.\010\010|cFFCC0000이 물건은 파괴되었습니다 명성|r"
rows["376:1157104861"]="와임레스트 협정을 깨고 그들의 주인의 재발을 방해하는 사람들을 꺾기 위해 블랙 드래곤 비행의 강력한 전쟁당 아제로스, 무서운 조울 용 하리온과 그의 부교인 사비안 라지파이어, 발타루스 워보너와 장군 자리트리아누스가 이끌고 와임레스트 성전 아래 루비 성원에 공격을 가했습니다."
rows["379:674439687"]="@ 플레이어에게 포기하지 마세요\010실라스 다크문에서 봉쇄된 카드 패키지에서 얻었습니다!\010\010이 스킬 카드 사용은 스킬 카드 컬렉션에서 그것을 잠금 할 것입니다. 당신의 스킬 카드 컬렉션은 영역의 모든 캐릭터와 공유되며, 당신은 스킬 카드 컬렉션을 메뉴에서 스킬 카드를 활성화할 수 있습니다.\010\010당신은 레벨 사이야 1 그리고 9 이 항목을 사용하려면, 가짜가 적어야 합니다. 20 이 항목을 사용하려면"
