rows["383:767073945"]="여러 유서품을 포함하는 캐시, 하지만 경험 증진을 제공하지 않습니다.\010 ⁇ 워크의 x2 밴드\010x1 강화된 힘의 방패\010x1 폼된 띠가 들어있어요\010x1 폼된 '마이트' 부츠\010x1  ⁇  닦은  ⁇  톱니\010 ⁇ 은  ⁇ 의  ⁇ 은 잎이 들어있어요\010x1  ⁇ 은 헬멧\010 ⁇ 한 손갑을 포함하고 있습니다"
rows["384:1002046683"]="목표물의 영혼을 배수하여 암흑 피해 이상으로 한다 목표물이 건강 상태 또는 그 이하 25%에 있다면, 배수 영혼은 정상적인 피해의 4배를 발생시킨다. 목표물이 배수되는 동안 사망하고 경험이나 명예를 가져오면 투수가 Soul Shard을 얻는다. 배수 영혼이 목표물을 손상시키는 때마다, 그것은 또한 Soul Shard을 생성할 기회를 가지고 있다. 다른 주문에 Soul Shards가 필요합니다."
rows["386:31125384"]="체인치리얼 또는 리프티드 투입을 할 때, 당신은 당신의 치료파 마술의 투입 시간을 줄이고, 두 번의 투입이 완료될 때까지 당신의 소형 치유파 마술의 중요한 효과 가능성을 %로 증가시킬 수 있습니다. 또한, 당신의 치유파는 보너스 치유 효과의 추가 효과를 얻으며, 당신의 소형 치유 파도는 추가적인 보너스 치유 효과가 있습니다."
rows["389:2038508402"]="- 그래요 17 저 망할 짐승이 내 캠프를 공격하고, 맥주를 한 잔처럼 날 잡아내고, 그의 냄새가 나는 동굴로 끌고 갔던 며칠이 지난 것. \010\010저녁식사할 줄 알았지만 큰 도마뱀은 내 발과 시계를  ⁇ 어 버립니다. \010\010어쨌든, 난  ⁇ 과 맥주를 마르지 않았어 그리고 다시 귀여운 수시에게 돌아 올거야"
rows["389:744762200"]="스컬지 침략 때 프리스킬라 케인 가 가족 에스텔 에서 도망쳤을 때, 그 들 의 하녀 와 종 들 은 다른 피난처 없이 맨션 내부 로 바리케이드 되어 있었다. 그러나 곧 그 들 은 외부 의 괴물 들 이 프리스킬라 가 태어난 괴물 들 보다 더 위험 하지 않는다는 걸 깨달았다. 그래서 그들은 동굴 을 봉쇄 하고 열쇠 를 세 조각으로 쪼개었다."
