rows["390:1831698098"]="무기의 피해를 발생시켜 현재 목표에 대한 주입을 새로워하고\010\010뱀 sting - 당신의 뱀 sting이 해친 피해의 40%를 즉시 처리합니다.\010\010바이퍼 스팅 - 당신의 바이퍼 스팅이 배출한 전체 양의 60%에 해당하는 마나을 즉시 당신에게 반환합니다.\010\010스코르피드 스팅 - 10 초 동안 목표물을 무력화하려는 시도. 이 효과는 1 분당 한 번 이상 발생할 수 없습니다."
