rows["399:1168147256"]="더 이상 새로운 능력을 발휘하지 않을 것입니다. 4 능력 본질은 얻은 수준 67 이 70 추가 레벨을 선택할 수 있도록 50 또는 60 재능은 레벨에 도달하면 70총 1천만원 12 지출 할 수 있는 능력 3 수준 50 그리고 60 재능은 선택만 할 수 있습니다 1 수준 60 이 아이템은 또한 당신이 더 이상 능력을 발휘하지 못하는 수준에서 운의 스크롤을 부여합니다!"
